use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use crate::shared::ids::{CheckId, DiagnosticReportId};

/// Hard cap on `DiagnosticReport::root_cause_summary`.
///
/// The summary is ALWAYS template-generated by the worker (see
/// `crates/worker/src/diagnostics.rs`) from a fixed, small set of format
/// strings built out of structured data the worker collected itself
/// (a resolved IP, an elapsed duration, a classified error kind, a
/// certificate expiry date, an HTTP status code) — it NEVER interpolates
/// raw response bodies, header values, or other user/server-controlled
/// text. This cap is a defense-in-depth backstop, enforced here at
/// construction so it can never be bypassed by a future call site, not
/// because a template-generated summary is expected to legitimately
/// approach this size.
pub const MAX_ROOT_CAUSE_SUMMARY_LENGTH: usize = 500;

/// Hard cap on `DiagnosticStep::detail`.
///
/// `detail` is also produced by the worker from fixed template strings,
/// never from raw response/header/body content. This cap mirrors
/// `MAX_ROOT_CAUSE_SUMMARY_LENGTH` and exists only as a backstop against
/// future call sites that might accidentally interpolate unbounded
/// server-controlled text. Enforced here at construction.
pub const MAX_DIAGNOSTIC_STEP_DETAIL_LENGTH: usize = 500;

/// The outcome of one diagnostic probe.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum DiagnosticStepStatus {
    Success,
    Failed,
    /// Never attempted because an earlier step in the same report already
    /// failed — diagnostics stop at the first failing step.
    Skipped,
}

/// One stage of a diagnostic run (e.g. "DNS resolution", "TCP connect",
/// "TLS handshake", "HTTP response").
///
/// `detail` is ALWAYS produced by the worker from structured data it
/// collected itself via fixed format strings — see
/// `crates/worker/src/diagnostics.rs`. It never echoes raw response
/// bodies or header values.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DiagnosticStep {
    pub name: String,
    pub status: DiagnosticStepStatus,
    pub duration_ms: u64,
    pub detail: String,
}

impl DiagnosticStep {
    pub fn new(
        name: impl Into<String>,
        status: DiagnosticStepStatus,
        duration_ms: u64,
        detail: impl Into<String>,
    ) -> Self {
        let mut detail = detail.into();
        if detail.chars().count() > MAX_DIAGNOSTIC_STEP_DETAIL_LENGTH {
            detail = detail
                .chars()
                .take(MAX_DIAGNOSTIC_STEP_DETAIL_LENGTH)
                .collect();
        }

        Self {
            name: name.into(),
            status,
            duration_ms,
            detail,
        }
    }

    pub fn skipped(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            status: DiagnosticStepStatus::Skipped,
            duration_ms: 0,
            detail: "Skipped: an earlier diagnostic step already failed".to_string(),
        }
    }
}

/// A diagnostic run performed immediately after a monitor's main check
/// failed, explaining WHY it went down (DNS / TCP / TLS / HTTP) rather
/// than just recording that it did.
///
/// `check_result_id` references the `Check` (persisted check execution)
/// this diagnostic run explains — one diagnostic report per failed check.
///
/// `root_cause_summary` is always template-generated by the worker (see
/// `crates/worker/src/diagnostics.rs::run_diagnostics`) — never built by
/// interpolating raw, unescaped response/header content. This is what
/// keeps it safe to render directly in a dashboard or email.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DiagnosticReport {
    pub id: DiagnosticReportId,
    pub check_result_id: CheckId,
    /// Denormalized copy of the referenced `Check`'s `checked_at`.
    ///
    /// Exists so `(check_id, check_checked_at)` can serve as a foreign
    /// key into `checks`. `checks.id` alone is sufficient today, but if
    /// `checks` is later partitioned by `checked_at` (see HANDOVER.md
    /// H15 assessment), PostgreSQL requires a partitioned table's primary
    /// key to include the partition key — forcing the primary key on
    /// `checks` to become `(id, checked_at)` and any foreign key into it
    /// to reference that whole composite key. Carrying this value here
    /// now means that future migration will not need to touch every
    /// existing `diagnostic_reports` row again.
    pub check_checked_at: DateTime<Utc>,
    pub steps: Vec<DiagnosticStep>,
    pub root_cause_summary: String,
    pub created_at: DateTime<Utc>,
}

impl DiagnosticReport {
    /// Creates a new diagnostic report. `root_cause_summary` is truncated
    /// (on a char boundary) to `MAX_ROOT_CAUSE_SUMMARY_LENGTH` if it
    /// somehow exceeds it — enforced here so the cap can never be
    /// bypassed regardless of what future call sites pass in.
    ///
    /// `check_checked_at` must be the `checked_at` value of the exact
    /// `Check` referenced by `check_result_id` — it is written verbatim
    /// alongside `check_id` and is what the composite foreign key into
    /// `checks(id, checked_at)` validates against.
    pub fn new(
        id: DiagnosticReportId,
        check_result_id: CheckId,
        check_checked_at: DateTime<Utc>,
        steps: Vec<DiagnosticStep>,
        root_cause_summary: impl Into<String>,
    ) -> Self {
        let mut summary = root_cause_summary.into();
        if summary.chars().count() > MAX_ROOT_CAUSE_SUMMARY_LENGTH {
            summary = summary
                .chars()
                .take(MAX_ROOT_CAUSE_SUMMARY_LENGTH)
                .collect();
        }

        Self {
            id,
            check_result_id,
            check_checked_at,
            steps,
            root_cause_summary: summary,
            created_at: Utc::now(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use uuid::Uuid;

    #[test]
    fn truncates_oversized_summary() {
        let long_summary = "a".repeat(600);
        let report = DiagnosticReport::new(
            DiagnosticReportId::new(),
            CheckId(Uuid::new_v4()),
            Utc::now(),
            vec![],
            long_summary,
        );

        assert_eq!(
            report.root_cause_summary.chars().count(),
            MAX_ROOT_CAUSE_SUMMARY_LENGTH
        );
    }

    #[test]
    fn truncates_oversized_step_detail() {
        let long_detail = "d".repeat(600);
        let step = DiagnosticStep::new(
            "HTTP response",
            DiagnosticStepStatus::Success,
            100,
            long_detail,
        );

        assert_eq!(
            step.detail.chars().count(),
            MAX_DIAGNOSTIC_STEP_DETAIL_LENGTH
        );
    }

    #[test]
    fn keeps_summary_under_cap_unchanged() {
        let report = DiagnosticReport::new(
            DiagnosticReportId::new(),
            CheckId(Uuid::new_v4()),
            Utc::now(),
            vec![],
            "DNS resolution failed after 5000ms",
        );

        assert_eq!(
            report.root_cause_summary,
            "DNS resolution failed after 5000ms"
        );
    }

    #[test]
    fn skipped_step_has_zero_duration() {
        let step = DiagnosticStep::skipped("TLS handshake");
        assert_eq!(step.status, DiagnosticStepStatus::Skipped);
        assert_eq!(step.duration_ms, 0);
    }
}
